import pytest

from app import normalize_optional_text


def test_none_returns_empty_string():
    assert normalize_optional_text(None) == ""


def test_plain_string_returned_unchanged():
    assert normalize_optional_text("hello") == "hello"


def test_string_is_stripped():
    assert normalize_optional_text("  hi  ") == "hi"


def test_whitespace_only_string_returns_empty():
    assert normalize_optional_text("   \t\n ") == ""


def test_empty_string_returns_empty():
    assert normalize_optional_text("") == ""


def test_leading_and_trailing_whitespace_removed():
    assert normalize_optional_text("\n\t padded \t\n") == "padded"


def test_internal_whitespace_preserved():
    assert normalize_optional_text("  a  b  ") == "a  b"


def test_input_string_not_modified():
    original = "  keep me  "
    normalize_optional_text(original)
    assert original == "  keep me  "


@pytest.mark.parametrize("value", [0, 1, -5, 3.14, True, False, [], ["a"], {}, {"a": 1}, b"bytes", (1, 2)])
def test_non_string_non_none_raises_type_error(value):
    with pytest.raises(TypeError):
        normalize_optional_text(value)

def normalize_optional_text(value):
    if value is None:
        return ""
    if not isinstance(value, str):
        raise TypeError("value must be str or None")
    return value.strip()

def normalize_optional_text(value):
