import pytest

from app import parse_count


def test_parses_plain_integer():
    assert parse_count("42", 7) == 42


def test_parses_with_leading_and_trailing_whitespace():
    assert parse_count("  42  ", 7) == 42


def test_parses_positive_sign():
    assert parse_count("+15", 0) == 15


def test_parses_negative_sign():
    assert parse_count("-15", 0) == -15


def test_parses_zero():
    assert parse_count("0", 99) == 0


def test_invalid_returns_supplied_default():
    assert parse_count("bad", 7) == 7


def test_invalid_returns_supplied_default_negative():
    assert parse_count("not-a-number", -3) == -3


def test_invalid_returns_zero_when_default_omitted():
    assert parse_count("bad") == 0


def test_empty_string_returns_default():
    assert parse_count("", 5) == 5


def test_whitespace_only_returns_default():
    assert parse_count("   ", 5) == 5


def test_float_like_string_returns_default():
    assert parse_count("3.5", 11) == 11


def test_non_str_int_raises_type_error():
    with pytest.raises(TypeError):
        parse_count(42, 7)


def test_non_str_none_raises_type_error():
    with pytest.raises(TypeError):
        parse_count(None)


def test_non_str_float_raises_type_error():
    with pytest.raises(TypeError):
        parse_count(3.5, 1)


def test_non_str_list_raises_type_error():
    with pytest.raises(TypeError):
        parse_count(["1"], 1)

def parse_count(text, default=0):
    if not isinstance(text, str):
        raise TypeError("text must be str")
    try:
        return int(text)
    except ValueError:
        return default

def parse_count(text, default=0):
    if not isinstance(text, str):
        raise TypeError("text must be str")
    try:
        return int(text)
    except ValueError:
        return default

